            tree[i].extend([int(x) for x in parts[1:]])
        elif parts[0] == "NOT":
            tree[i].append(int(parts[1]))

# Function to evaluate the tree
def evaluate(node, new_value):
    if isinstance(values[node], int):
        return values[node]
    children = tree[node]
    if values[children[0]] == 0 and values[children[1]] == 0:
